begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select plan(11);
-- Disposable records and configuration changes roll back at the end.
insert into auth.users(id,email,email_confirmed_at) values('eeeeeeee-0000-4000-8000-000000000001','approval-test@example.test',now());
insert into auth.sessions(id,user_id,aal) values('eeeeeeee-0000-4000-8000-000000000002','eeeeeeee-0000-4000-8000-000000000001','aal2');
insert into band_finance.workspaces(id,name,legal_name,abn,provider_employer_ref,mandate_ref) values('eeeeeeee-0000-4000-8000-000000000003','SQL test','Synthetic payer','12345678901','test-employer','test-mandate');
insert into band_finance.people(workspace_id,id,name,email,fund_status,provider_member_ref) values('eeeeeeee-0000-4000-8000-000000000003','eeeeeeee-0000-4000-8000-000000000004','Test recipient','recipient@example.test','verified','test-member');
insert into band_finance.memberships(workspace_id,user_id,role,can_approve) values('eeeeeeee-0000-4000-8000-000000000003','eeeeeeee-0000-4000-8000-000000000001','owner',true);
insert into band_finance.gigs(workspace_id,id,title,performance_date,payday,draft) values('eeeeeeee-0000-4000-8000-000000000003','eeeeeeee-0000-4000-8000-000000000005','SQL fixture','2026-10-23','2026-10-26','{}');
insert into band_finance.engagements(workspace_id,id,gig_id,person_id,terms,response) values('eeeeeeee-0000-4000-8000-000000000003','eeeeeeee-0000-4000-8000-000000000006','eeeeeeee-0000-4000-8000-000000000005','eeeeeeee-0000-4000-8000-000000000004','{}','accepted');
insert into band_finance.revisions(workspace_id,id,gig_id,gig_version,input,result,digest,rule_version,created_by) values('eeeeeeee-0000-4000-8000-000000000003','eeeeeeee-0000-4000-8000-000000000007','eeeeeeee-0000-4000-8000-000000000005',1,'{}','{"balance":0,"residual":0,"upcomingCashBeforeRecordedTransfers":11200,"allocations":[{"id":"eeeeeeee-0000-4000-8000-000000000006","super":1200}]}','test-digest','test-rule','eeeeeeee-0000-4000-8000-000000000001');
update finance_private.configuration set environment='sandbox',provider_ready=true,submission_enabled=true,deadline_rules_reviewed=true,funding_method='test-only',provider_fee_cents=0;
select set_config('request.jwt.claims','{"sub":"eeeeeeee-0000-4000-8000-000000000001","session_id":"eeeeeeee-0000-4000-8000-000000000002","aal":"aal2","role":"authenticated"}',true);
create temporary table test_context(run uuid, digest text, approval uuid, claimed jsonb);
grant all on test_context to authenticated;
set local role authenticated;
insert into test_context(run) select band_finance.prepare_run('eeeeeeee-0000-4000-8000-000000000003','eeeeeeee-0000-4000-8000-000000000007',11200,'Test funding evidence');
update test_context set digest=(select p.digest from band_finance.pay_runs p where p.id=test_context.run);
select ok((select run is not null from test_context),'prepared a reviewed sandbox snapshot');
update test_context set approval=band_finance.authorise_run('eeeeeeee-0000-4000-8000-000000000003',run,digest,'eeeeeeee-0000-4000-8000-000000000008');
select is((select band_finance.authorise_run('eeeeeeee-0000-4000-8000-000000000003',run,digest,'eeeeeeee-0000-4000-8000-000000000008') from test_context),(select approval from test_context),'identical approval replay returns same approval');
select is((select count(*)::integer from band_finance.approvals where workspace_id='eeeeeeee-0000-4000-8000-000000000003'),1,'one approval');
select is((select count(*)::integer from band_finance.outbox_jobs where workspace_id='eeeeeeee-0000-4000-8000-000000000003'),1,'one outbox job committed with approval');
select throws_ok('select band_finance.claim_job()','42501','permission denied for function claim_job','ordinary owner cannot execute worker');
reset role;
update test_context set claimed=band_finance.claim_job();
select is((select claimed->>'action' from test_context),'submit','first lease allows one submission attempt');
select band_finance.mark_submission_started('eeeeeeee-0000-4000-8000-000000000003',(claimed->'job'->>'id')::uuid,(claimed->'job'->>'lease_token')::uuid) from test_context;
update band_finance.outbox_jobs set lease_until=now()-interval '1 second' where workspace_id='eeeeeeee-0000-4000-8000-000000000003';
update test_context set claimed=band_finance.claim_job();
select is((select claimed->>'action' from test_context),'reconcile','restart after submission marker reconciles rather than resubmits');
select is((select count(*)::integer from band_finance.outbox_jobs where workspace_id='eeeeeeee-0000-4000-8000-000000000003' and attempts=1),1,'retry did not increase submission attempts');
update band_finance.people set destination_version=destination_version+1 where workspace_id='eeeeeeee-0000-4000-8000-000000000003';
update band_finance.outbox_jobs set lease_until=now()-interval '1 second' where workspace_id='eeeeeeee-0000-4000-8000-000000000003';
select is(band_finance.claim_job(),null::jsonb,'changed destination blocks worker');
select is((select state from band_finance.outbox_jobs where workspace_id='eeeeeeee-0000-4000-8000-000000000003'),'blocked','blocked job cannot silently retry');
delete from auth.sessions where id='eeeeeeee-0000-4000-8000-000000000002';
set local role authenticated;
select is(band_finance.role_for('eeeeeeee-0000-4000-8000-000000000003'),null::text,'revoked session loses workspace authority immediately');
reset role;
select * from finish();
rollback;
